{
  "contract": "X7DAOLiquidityHub",
  "closure": {
    "site_function": "processFees",
    "site_call": ".call",
    "functions": [
      "<fallback>",
      "processFees",
      "sendDistributeBalance",
      "sendTreasuryBalance"
    ],
    "justification": "These functions interact with the exposed balances and can be re-entered during the callback."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>",
      "sendDistributeBalance",
      "sendTreasuryBalance"
    ],
    "nesting_bound": {
      "processFees": 1
    }
  },
  "phases": {
    "function": "processFees",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "The amount of balance in transit during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "distributeBalance + auxiliaryBalance + treasuryBalance + liquidityBalance + inFlight <= _ethBal",
    "stable_formula": "distributeBalance + auxiliaryBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "distributeBalance + auxiliaryBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "rule": "The exposure invariant ensures that the total of all balances does not exceed the ETH balance, even during reentrant calls."
  }
}
